VALUES ('93b660dd-cf67-5de9-9a10-8dab458c4c64', (SELECT sys_role_id FROM sys_role WHERE name = 'User'), 'c05fd902-ed8c-51d5-ab92-769a217755c4', '532839f6-7082-524c-86b4-13e17cc2dfb7', 'R', TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
