INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a25ed307-2697-5299-83fa-bd641bb399cf', '4de9cd9d-b69c-5adc-906f-c97fa4af0b9c', 'bcdc50d2-3497-5c37-bbf2-846c2f0e8d1a', 'fbd956d9-615b-5d01-a889-c05dd3ece722', 'Code', 'Standard business code for the unit, such as EACH, KG, L, HOUR, or DAY. Used in forms, integrations, documents, validation, and quantity display. Code identifies the unit definition; it does not represent a conversion or quantity itself. Used to resolve units during order entry, purchasing, receipt, inventory, invoicing, and reporting. Required for operational interoperability. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Unit Of Measure already uses this value. Up to 30 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
