VALUES ('a8185f9e-7a9e-5d1b-81ad-c7ec7b226845', '4de9cd9d-b69c-5adc-906f-c97fa4af0b9c', '6fa5c760-e32a-5c55-a60c-922b5bc2738a', 'c1461456-1ff4-551b-8b77-a45dcc0311e0', 'Symbol', 'Standard display symbol for the unit. Used for compact display in documents, labels, reports, and interfaces. Symbol is presentation metadata and does not replace the canonical unit code. Improves human-readable representation of quantities. Optional when the unit has no standard symbol or display policy does not require one. Up to 20 characters.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
