INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bc3c8312-3dea-5d7c-937a-c4fb6e52a9cf', '7e7d0348-9cd7-5ed5-9226-e924958444f4', 'product_id', 'Product', 'Product whose inventory state is affected. Connects event to product master, units and policies. Exactly one product is affected. Identifies stock item.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
