INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9d8d84b4-0569-5cf2-94d3-d9869950d250', '38b595a2-91c9-51c2-9e36-2c94d66ed6d8', 'status', 'Status', 'The status of the inventory reservation: a value the business records on it. Entered or maintained when a inventory reservation is created or changed; shown on its form and available to search and reports. Read together with the inventory reservation''s other fields and its relationships; it is not meaningful on its own. Required: a inventory reservation cannot be understood without its status. The status of the inventory reservation is pending; set it when that is what the business means for this record. The status of the inventory reservation is active; set it when that is what the business means for this record. The status of the inventory reservation is partially consumed; set it when that is what the business means for this record. The status of the inventory reservation is released; set it when that is what the business means for this record. The status of the inventory reservation is consumed; set it when that is what the business means for this record. The status of the inventory reservation is cancelled; set it when that is what the business means for this record. The status of the inventory reservation is expired; set it when that is what the business means for this record.', 1010, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
