VALUES ('30afd183-bd47-5717-8358-6a70c846b042', '38b595a2-91c9-51c2-9e36-2c94d66ed6d8', 'product_id', 'Product', 'Links a inventory reservation to product, the product it relates to. Chosen from the existing product records when the inventory reservation is created or edited. A inventory reservation has exactly one product in this role. Lets the inventory reservation be found from, and reported with, its product.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
