VALUES ('0ddfc296-a25f-519f-8a45-b11ae4d5c88b', '18172ff1-5ea9-5221-8090-9c32a8a1f172', 'parent_location_id', 'Parent Location', 'The parent location id of the location: a link to another record the business records on it. Entered or maintained when a location is created or changed; shown on its form and available to search and reports. Read together with the location''s other fields and its relationships; it is not meaningful on its own.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
