VALUES ('e8ed274b-9b62-58db-a7bd-d86e0ec06b4c', '18172ff1-5ea9-5221-8090-9c32a8a1f172', 'organization_id', 'Organization', 'Links a location to organization, the organization it relates to. Chosen from the existing organization records when the location is created or edited. A location has at most one organization in this role. Lets the location be found from, and reported with, its organization.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
