VALUES ('035f67c4-c17a-564c-96c9-4c1b5b8f28e3', 'bus_currency_status', 'Currency Status', 'The values of currency status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, 'bf13e493-9f06-53b2-869f-c5575d831bdf', 'U', TRUE, 'system', 'system', NOW(), NOW())
