VALUES ('0b8f1094-617d-513f-8e60-8b3bef2c9ff4', 'bus_task_priority', 'Task Priority', 'The values of task priority, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '0828a723-3794-5272-810c-1e2ab9cfd4d3', 'U', TRUE, 'system', 'system', NOW(), NOW())
