VALUES ('54a71309-f7db-52fd-907c-ba99d2fde5d9', 'bus_product_status', 'Product Status', 'The values of product status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, 'f62e5bfc-5885-536e-bd5f-b1901a4b6fda', 'U', TRUE, 'system', 'system', NOW(), NOW())
