-- --------------------------------------------------------------------------
-- Inventory Location (bus_inventory_location)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('21312616-21ce-5dc9-a3fb-2aac8f694a85', 'bus_inventory_location', 'Inventory Location', 'Granular inventory position whose lifecycle controls future execution while preserving historical inventory state. A location is operational infrastructure, not merely an address. Changing its status can affect receiving, put-away, reservations, picking, transfers, replenishment and shipment staging. Receiving, warehouse execution, picking, replenishment, stock counting, transfers, reservation, fulfillment, quarantine and yard operations. Warehouse supplies facility context. InventoryLocation supplies operational position. InventoryBalance supplies current state. InventoryMovement supplies historical event evidence. InventoryReservation supplies committed demand. Location create → configure capacity/type → activate → participate in receiving/put-away/reservation/picking/transfer → block or quarantine when necessary → resolve dependent stock/reservations → inactive. Status changes trigger dependency validation rather than simply toggling a flag. Location status changes affect future transaction eligibility; location hierarchy/warehouse changes require validation of balances and open reservations; capacity/type changes require validation of affected put-away and transfer rules; historical movements remain unchanged. Configured → ACTIVE → BLOCKED/QUARANTINE operational state → resolved or INACTIVE. Existing stock is retained and must be deliberately relocated or handled through authorized workflow. A storage rack is blocked because of damage. New put-away and allocation are stopped. Existing stock and reservations are identified; reservations are moved or released and stock is transferred to valid locations. Historical movements still point to the original rack.', 'boxes', 'A', FALSE, FALSE, FALSE, TRUE, '7e4b220e-a737-5ee6-ab11-d39c06e8de5a', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8fd7be8d-2100-5e59-95c4-5da41d990fb4', '7e4b220e-a737-5ee6-ab11-d39c06e8de5a', '21312616-21ce-5dc9-a3fb-2aac8f694a85', 'Inventory Location', 'Shows one Inventory Location at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Warehouse and Warehouse Zone are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fa304156-0842-567b-821b-f0c0c31c59b5', '21312616-21ce-5dc9-a3fb-2aac8f694a85', 'id', 'Id', 'The inventory location id of the inventory location: an identifier the business records on it. Entered or maintained when a inventory location is created or changed; shown on its form and available to search and reports. Read together with the inventory location''s other fields and its relationships; it is not meaningful on its own. Required: a inventory location cannot be understood without its inventory location id.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9544a3af-faa9-5e73-85f7-da3dcbf29903', '21312616-21ce-5dc9-a3fb-2aac8f694a85', 'code', 'Code', 'The code of the inventory location: a value the business records on it. Entered or maintained when a inventory location is created or changed; shown on its form and available to search and reports. Read together with the inventory location''s other fields and its relationships; it is not meaningful on its own. Required: a inventory location cannot be understood without its code.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f9f61969-040d-5e52-9d1e-54204fd338a9', '21312616-21ce-5dc9-a3fb-2aac8f694a85', 'location_type', 'Location Type', 'The location type of the inventory location: a value the business records on it. Entered or maintained when a inventory location is created or changed; shown on its form and available to search and reports. Read together with the inventory location''s other fields and its relationships; it is not meaningful on its own. Required: a inventory location cannot be understood without its location type. The location type of the inventory location is receiving; set it when that is what the business means for this record. The location type of the inventory location is bin; set it when that is what the business means for this record. The location type of the inventory location is shelf; set it when that is what the business means for this record. The location type of the inventory location is rack; set it when that is what the business means for this record. The location type of the inventory location is floor; set it when that is what the business means for this record. The location type of the inventory location is pick; set it when that is what the business means for this record. The location type of the inventory location is staging; set it when that is what the business means for this record. The location type of the inventory location is quarantine; set it when that is what the business means for this record. The location type of the inventory location is yard slot; set it when that is what the business means for this record. The location type of the inventory location is other; set it when that is what the business means for this record.', 1007, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b67d9e21-b67e-59ee-90b4-168d1cff22d4', '21312616-21ce-5dc9-a3fb-2aac8f694a85', 'status', 'Status', 'Controls whether the location can participate in normal future inventory operations. Applies to receiving, put-away, picking, transfer, allocation, replenishment, counting and staging. Status constrains future operations; it never deletes current balances or historical movements. Status changes trigger dependent-workflow validation before operational eligibility changes become effective. The status of the inventory location is active; set it when that is what the business means for this record. The status of the inventory location is blocked; set it when that is what the business means for this record. The status of the inventory location is inactive; set it when that is what the business means for this record.', 1008, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
