INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1dff25e9-d6cb-5c5c-8cb2-b3beffe2545d', 'bus_dock', 'Dock', 'Warehouse loading/receiving execution resource. Dock is a physical process resource, not an inventory location unless separately represented by stagingLocation. Inbound, outbound, cross-dock, appointment, staging and loading workflows. Warehouse owns operational context; InventoryLocation supplies stock-control context; Shipment supplies transport work. Configured → active/restricted → retired with historical execution retained.', 'database', 'A', FALSE, FALSE, FALSE, TRUE, '7e4b220e-a737-5ee6-ab11-d39c06e8de5a', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
