-- --------------------------------------------------------------------------
-- Inventory Balance (bus_inventory_balance)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6a3a3f01-34fb-50b2-a5fe-1a5ef4422c46', 'bus_inventory_balance', 'Inventory Balance', 'Current inventory state projection maintained from authoritative inventory events and reservation workflows. InventoryBalance answers the current operational question of what is on hand, reserved and available. InventoryMovement remains the historical ledger; reservation events explain commitment state. Inventory control, warehouse management, order fulfillment, purchasing, maintenance, replenishment, planning and availability. Product defines the stocked item, UnitOfMeasure defines quantity semantics, InventoryLocation defines where stock is held, InventoryMovement records physical/logical stock events, and reservation workflows govern committed quantity. Source transaction → authorization → posted inventory event → InventoryBalance projection. Reservations update commitment state without physical movement. Product/UOM/Location changes trigger dependent-workflow validation rather than direct balance mutation. Allocation and issue must protect against concurrent consumption of the same available quantity using transactional locking, optimistic concurrency or equivalent controls. Created when a Product/location combination becomes inventory-relevant → continuously projected from events → reconciled through controlled stock counts/adjustments → retained at zero when history remains relevant. 100 units are received, 20 are reserved, and 3 are issued. The projection becomes 97 on-hand and, depending on the reservation workflow, 17 reserved and 80 available. If the product UOM conversion later changes, existing stock is not silently reinterpreted; a controlled conversion/reconciliation workflow is required.', 'boxes', 'A', FALSE, FALSE, FALSE, TRUE, '7e4b220e-a737-5ee6-ab11-d39c06e8de5a', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b1d506f6-ad67-5180-83c3-e85174a63b9d', '7e4b220e-a737-5ee6-ab11-d39c06e8de5a', '6a3a3f01-34fb-50b2-a5fe-1a5ef4422c46', 'Inventory Balance', 'Shows one Inventory Balance at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product, Inventory Location and Lot are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 2, 50, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b3bdb4a8-f767-57e6-8174-b32112d2ba91', '6a3a3f01-34fb-50b2-a5fe-1a5ef4422c46', 'id', 'Id', 'Immutable identity of the inventory state projection. Used to reference and reconcile current stock state independently of movement events. Identifies one Product/location state projection rather than a Product or location itself. Provides the current state consumed by allocation, fulfillment, replenishment and inventory control.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9b15821b-498e-53cb-9a58-074eec5d59fd', '6a3a3f01-34fb-50b2-a5fe-1a5ef4422c46', 'quantity_on_hand', 'Quantity On Hand', 'Physical quantity currently recorded as present at the location. Stock visibility, replenishment, counting, fulfillment and inventory control. Represents physical stock and is distinct from reserved and available quantities. Derived from posted receipt, issue, transfer, return and adjustment movements.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fee2d298-3585-52a5-a3e2-2cfa1e5bd1ff', '6a3a3f01-34fb-50b2-a5fe-1a5ef4422c46', 'quantity_reserved', 'Quantity Reserved', 'Portion of on-hand stock committed to approved demand. Allocation and fulfillment planning. Reservations normally do not change physical on-hand quantity. Derived from active reservation/release workflows and adjusted when fulfillment consumes or releases a reservation.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0e05de3c-de94-5dd4-a358-04650b89fa12', '6a3a3f01-34fb-50b2-a5fe-1a5ef4422c46', 'quantity_available', 'Quantity Available', 'Quantity eligible for new allocation after reservations and applicable restrictions. Availability checks, fulfillment, replenishment and planning. Normally equals on-hand minus reserved before additional restrictions. Must be recalculated atomically with reservation and movement state changes.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8a0bc226-5b83-571d-858a-6301313e7e3a', '6a3a3f01-34fb-50b2-a5fe-1a5ef4422c46', 'last_updated_at', 'Last Updated At', 'Timestamp of the latest material projection update. Concurrency, synchronization, cache freshness, audit and integration. Does not replace movement or reservation event timestamps. Supports stale-state detection during allocation and issue processing.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('50bcfaf7-b590-55bc-af16-285d8d5c9cfe', '6a3a3f01-34fb-50b2-a5fe-1a5ef4422c46', 'product_id', 'Product', 'Links a inventory balance to product, the product it relates to. Chosen from the existing product records when the inventory balance is created or edited. A inventory balance has exactly one product in this role. Lets the inventory balance be found from, and reported with, its product.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4316c2a9-27c8-5f90-853b-2652f9f2c11c', '6a3a3f01-34fb-50b2-a5fe-1a5ef4422c46', 'inventory_location_id', 'Inventory Location', 'Links a inventory balance to inventory location, the inventory location it relates to. Chosen from the existing inventory location records when the inventory balance is created or edited. A inventory balance has exactly one inventory location in this role. Lets the inventory balance be found from, and reported with, its inventory location.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bf4a55a2-3a4c-5e64-9049-02c2b5271dee', '6a3a3f01-34fb-50b2-a5fe-1a5ef4422c46', 'lot_id', 'Lot', 'Lot segment represented by this balance when lot-controlled. Separates stock state by batch for quality, expiry, and recall. Allocation, FEFO, recall, and reconciliation. Optional for non-lot-controlled products. Balance must reconcile to lot-attributed movements.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
